mapper.select:
SELECT l.loan_id, l.industry_id, l.region_id, l.company_name, l.product_name, l.begin_date, l.end_date, l.min_limit, l.max_limit, l.basic_rate, , COALESCE(lbc.bookmark_count, 0) AS bookmarkCount FROM loans l LEFT JOIN rates r ON l.loan_id = r.loan_id LEFT JOIN loan_bookmark_counts lbc ON l.loan_id = lbc.loan_id
l.industry_id = #{requestDto.industryId}
AND r.rate_type = '대출금리'
GROUP BY l.loan_id, l.industry_id, l.region_id, l.company_name, l.product_name, l.begin_date, l.end_date, l.min_limit, l.max_limit, l.basic_rate, lbc.bookmark_count ORDER BY l.begin_date DESC LIMIT #{requestDto.size} OFFSET #{requestDto.offset}
